from __future__ import annotations

import json
import logging
import os
import tempfile
from datetime import date
from pathlib import Path
from typing import Optional

from pydantic import BaseModel

logger = logging.getLogger(__name__)

HABITS_FILE = "habits.json"


class Habit(BaseModel):
    name: str
    created_at: date
    checkins: list[date] = []


class StreakState(BaseModel):
    current_streak: int = 0
    longest_streak: int = 0
    last_checkin: Optional[date] = None


class _StoreData(BaseModel):
    habits: dict[str, Habit] = {}


class HabitStore:
    def __init__(self, data_dir: Path) -> None:
        self._data_dir = Path(data_dir)
        self._file = self._data_dir / HABITS_FILE
        self._data = _StoreData()

    def load(self) -> HabitStore:
        self._data_dir.mkdir(parents=True, exist_ok=True)

        if not self._file.exists():
            self._data = _StoreData()
            self.save()
            return self

        try:
            raw = self._file.read_text(encoding="utf-8")
            self._data = _StoreData.model_validate_json(raw)
        except (json.JSONDecodeError, ValueError) as exc:
            logger.warning("Corrupt %s — resetting (cause: %s)", self._file, exc)
            self._data = _StoreData()
            self.save()

        return self

    def save(self) -> None:
        payload = self._data.model_dump_json(indent=2)
        self._data_dir.mkdir(parents=True, exist_ok=True)

        fd, tmp_path = tempfile.mkstemp(
            dir=self._data_dir, prefix=".habits-", suffix=".tmp"
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write(payload)
                f.write("\n")
            os.replace(tmp_path, self._file)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def get_habit(self, name: str) -> Optional[Habit]:
        return self._data.habits.get(name)

    def list_habits(self) -> list[Habit]:
        return list(self._data.habits.values())

    def add_habit(self, name: str) -> Habit:
        name = name.strip()
        if not name:
            raise ValueError("habit name must not be empty")
        if name in self._data.habits:
            raise ValueError(f"habit '{name}' already exists")

        habit = Habit(name=name, created_at=date.today())
        self._data.habits[name] = habit
        self.save()
        return habit

    def delete_habit(self, name: str) -> bool:
        if name not in self._data.habits:
            return False
        del self._data.habits[name]
        self.save()
        return True

    def get_checkins(self, name: str) -> list[date]:
        habit = self._data.habits.get(name)
        if habit is None:
            return []
        return list(habit.checkins)

    def with_lock(self):
        """Context manager that acquires an exclusive file lock around operations."""
        return _LockCtx(self._file)


class _LockCtx:
    """File-lock context manager. Uses flock on Unix; no-op on Windows."""

    def __init__(self, path: Path) -> None:
        self._path = path

    def __enter__(self) -> None:
        try:
            import fcntl  # noqa: TC002

            self._fd = os.open(str(self._path), os.O_RDWR | os.O_CREAT)
            fcntl.flock(self._fd, fcntl.LOCK_EX)
        except ImportError:
            # Windows — no flock support; proceed without locking
            self._fd = None

    def __exit__(self, *args: object) -> None:
        if self._fd is not None:
            try:
                import fcntl  # noqa: TC002

                fcntl.flock(self._fd, fcntl.LOCK_UN)
            except ImportError:
                pass
            os.close(self._fd)

