from datetime import date, timedelta

from streak_cli.store import HabitStore


def checkin(store: HabitStore, name: str) -> str:
    """Add today's checkin to *name*. Returns a status message."""
    habit = store.get_habit(name)
    if habit is None:
        return f"Error: habit '{name}' does not exist"

    today = date.today()
    if today in habit.checkins:
        return f"Already checked in to '{name}' for today"

    habit.checkins.append(today)
    store.save()
    return f"Checked in to '{name}' on {today}"


def compute_streaks(store: HabitStore) -> list[dict]:
    """Compute streak stats for every habit. Returns a list of dicts."""
    today = date.today()
    results: list[dict] = []

    for habit in store.list_habits():
        sorted_checkins = sorted(set(habit.checkins))

        if not sorted_checkins:
            results.append(
                {
                    "name": habit.name,
                    "current_streak": 0,
                    "longest_streak": 0,
                    "last_checkin": None,
                    "total_checkins": 0,
                }
            )
            continue

        last_checkin = sorted_checkins[-1]

        # --- current streak: consecutive days ending today or yesterday ---
        current = 0
        cursor = last_checkin
        while cursor in sorted_checkins:
            current += 1
            cursor -= timedelta(days=1)
        # Streak is alive only if last_checkin is today or yesterday
        if last_checkin < today - timedelta(days=1):
            current = 0

        # --- longest streak: walk the sorted list once ---
        longest = 1
        run = 1
        for i in range(1, len(sorted_checkins)):
            if sorted_checkins[i] - sorted_checkins[i - 1] == timedelta(days=1):
                run += 1
            else:
                run = 1
            if run > longest:
                longest = run

        results.append(
            {
                "name": habit.name,
                "current_streak": current,
                "longest_streak": longest,
                "last_checkin": last_checkin,
                "total_checkins": len(habit.checkins),
            }
        )

    return results


def format_streaks_table(streaks: list[dict]) -> str:
    """Return a readable text table for terminal output."""
    if not streaks:
        return "No habits tracked yet."

    headers = ["Habit", "Current", "Longest", "Last Checkin", "Total"]
    rows: list[list[str]] = [headers]

    for s in streaks:
        last = s["last_checkin"]
        last_str = last.strftime("%Y-%m-%d") if last else "—"
        rows.append(
            [
                s["name"],
                str(s["current_streak"]),
                str(s["longest_streak"]),
                last_str,
                str(s["total_checkins"]),
            ]
        )

    col_widths = [
        max(len(row[i]) for row in rows) for i in range(len(headers))
    ]

    # Header
    header_line = "  ".join(h.ljust(w) for h, w in zip(headers, col_widths))
    sep = "  ".join("-" * w for w in col_widths)

    lines = [header_line, sep]
    for row in rows[1:]:
        lines.append("  ".join(cell.ljust(w) for cell, w in zip(row, col_widths)))

    return "\n".join(lines)
